package be.winnetrie.mod.simpleserverutilities.network;
import be.winnetrie.mod.simpleserverutilities.SimpleServerUtilities;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.Identifier;
public record JailDashboardPayload(String json,String notice,boolean error) implements CustomPacketPayload{public static final Type<JailDashboardPayload> TYPE=new Type<>(Identifier.fromNamespaceAndPath(SimpleServerUtilities.MODID,"jail_dashboard"));public static final StreamCodec<RegistryFriendlyByteBuf,JailDashboardPayload> STREAM_CODEC=StreamCodec.of((b,p)->{b.writeUtf(p.json,32767);b.writeUtf(p.notice,512);b.writeBoolean(p.error);},b->new JailDashboardPayload(b.readUtf(32767),b.readUtf(512),b.readBoolean()));public JailDashboardPayload{json=PayloadBounds.string(json,32767);notice=PayloadBounds.string(notice,512);}@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}}
